/**
 * Constructor for the built-in HTTP session channel. The runtime always
 * mounts this channel; authors use `defineChannel` for custom surfaces.
 */
import { brandDefinition } from "./brand.js";
import { normalizeIdentity } from "./continuation-identity.js";
import { attachHttpControlPlaneAdmission } from "./http-control-plane-session.js";
/**
 * Configure the built-in HTTP session channel. Used by discovery as the
 * default (and for an optional internal `agent/channels/http.ts` override).
 */
export function httpChannel(config = {}) {
    const definition = config.continuation !== undefined
        ? brandDefinition("http-channel", {
            ...config,
            continuation: normalizeIdentity(config.continuation, "http"),
        })
        : brandDefinition("http-channel", config);
    attachHttpControlPlaneAdmission(definition);
    return definition;
}
